// ─── Global assertion flag ────────────────────────────────────────────────────

let __assertionsEnabled = false;

/**
 * Enable runtime assertions. When enabled, getAssertionsForFn() returns live
 * assertion objects. When disabled (default), getAssertionsForFn() returns null.
 *
 * Assertions are auto-enabled by NETHACK_JS_ASSERTIONS=1 at module load time,
 * or explicitly via enableAssertions() (used by the replay runner).
 *
 * The replay runner calls enableAssertions() before each replay session and
 * disableAssertions() after. This ensures assertions only fire during
 * instrumented replay, not during normal contest execution.
 */
export function enableAssertions()  { __assertionsEnabled = true;  }
export function disableAssertions() { __assertionsEnabled = false; }
export function assertionsEnabled() { return __assertionsEnabled;  }

// Auto-enable from environment (dev-runner integration).
if (ENV.NETHACK_JS_ASSERTIONS === '1') {
    __assertionsEnabled = true;
}

// ─── State comparison helpers ─────────────────────────────────────────────────

/**
 * Compare a captured state_before ([{key, val}] list) to a live state dump.
 *
 * Returns true if ALL keys in capturedBefore are present in liveState with
 * matching string values. Keys in liveState not in capturedBefore are ignored
 * (subset matching — captures may use fewer than 48 keys).
 *
 * Empty capturedBefore (pure functions with no relevant state) always matches.
 */
function compareStateBefore(capturedBefore, liveStateBefore) {
    if (!Array.isArray(capturedBefore) || capturedBefore.length === 0) return true;
    const liveByKey = new Map();
    for (const e of (liveStateBefore || [])) liveByKey.set(e.key, String(e.val));
    for (const e of capturedBefore) {
        const live = liveByKey.get(e.key);
        if (live === undefined || live !== String(e.val)) return false;
    }
    return true;
}

/**
 * Compare captured args to the args passed to the JS function.
 * Null/undefined on either side matches null/undefined on the other
 * (void-argument functions).
 */
function compareArgs(capturedArgs, jsArgs) {
    if (capturedArgs === null || capturedArgs === undefined) {
        // void-arg: jsArgs null/undefined or empty object both match
        if (jsArgs === null || jsArgs === undefined) return true;
        return Object.keys(capturedArgs || {}).length === 0;
    }
    if (jsArgs === null || jsArgs === undefined) {
        return Object.keys(capturedArgs).length === 0;
    }
    for (const [k, v] of Object.entries(capturedArgs)) {
        if (String(v) !== String(jsArgs[k])) return false;
    }
    return true;
}

/**
 * Find the best matching captured record for (fnName, jsArgs, liveStateBefore).
 *
 * Pass 1: full match on state_before + args.
 * Pass 2: state_before match only (void-arg functions where args is null).
 *
 * Returns the matched record or null if none found.
 */
function findMatchingRecord(fnName, jsArgs, liveStateBefore) {
    const records = EMBEDDED_RECORDS[fnName];
    if (!records || records.length === 0) return null;
    for (const rec of records) {
        if (compareStateBefore(rec.state_before, liveStateBefore)
            && compareArgs(rec.args, jsArgs)) {
            return rec;
        }
    }
    // Second pass: state-only (for void-arg functions)
    for (const rec of records) {
        if ((rec.args === null || rec.args === undefined)
            && compareStateBefore(rec.state_before, liveStateBefore)) {
            return rec;
        }
    }
    return null;
}

// ─── Assertion logic ──────────────────────────────────────────────────────────

/**
 * Check return value parity (mirrors runner.mjs buildHelpers assertReturnEqual).
 * Returns { ok: true } or { ok: false, message }.
 */
function checkReturnValue(jsResult, capturedReturn) {
    if ((jsResult === null || jsResult === undefined)
        && (capturedReturn === null || capturedReturn === undefined)) {
        return { ok: true };
    }
    const canBig = (v) => (
        typeof v === 'bigint'
        || (typeof v === 'number' && Number.isInteger(v))
        || (typeof v === 'string' && /^-?\d+$/.test(v))
    );
    if (canBig(jsResult) && canBig(capturedReturn)) {
        const a = BigInt(jsResult), b = BigInt(capturedReturn);
        if (a === b) return { ok: true };
        return { ok: false, message: 'return mismatch: js=' + a + ' captured=' + b };
    }
    const safeStr = (v) => JSON.stringify(v, (_k, val) =>
        typeof val === 'bigint' ? val.toString() : val);
    const jsStr = safeStr(jsResult), cStr = safeStr(capturedReturn);
    if (jsStr === cStr) return { ok: true };
    return { ok: false, message: 'return mismatch: js=' + jsStr + ' captured=' + cStr };
}

/**
 * Check state_after_diff parity.
 *
 * capturedDiff:     [{key, val}] — keys C changed, with new values.
 * liveStateBefore:  [{key, val}] — JS pre-call state snapshot.
 * liveStateAfter:   [{key, val}] — JS post-call state dump.
 *
 * Returns { ok: true } or { ok: false, problems: string[] }.
 * Logic mirrors runner.mjs buildHelpers assertStateAfterDiff.
 */
function checkStateAfterDiff(capturedDiff, liveStateBefore, liveStateAfter) {
    const problems = [];
    const beforeByKey = new Map();
    for (const e of (liveStateBefore || [])) beforeByKey.set(e.key, String(e.val));
    const afterByKey = new Map();
    for (const e of (liveStateAfter || [])) afterByKey.set(e.key, String(e.val));
    const expectedByKey = new Map();
    for (const e of (capturedDiff || [])) expectedByKey.set(e.key, String(e.val));

    for (const [k, expected] of expectedByKey) {
        const got = afterByKey.get(k);
        if (got === undefined) {
            problems.push('  ' + k + ' = ' + expected + '  (JS left unchanged — port gap)');
        } else if (got !== expected) {
            problems.push('  ' + k + ': expected ' + expected + ' got ' + got + '  (DIVERGED)');
        }
    }
    for (const [k, afterVal] of afterByKey) {
        if (!expectedByKey.has(k)) {
            const beforeVal = beforeByKey.get(k);
            if (beforeVal !== afterVal) {
                problems.push('  ' + k + ' = ' + afterVal + '  (JS changed but C did not — extra write)');
            }
        }
    }
    return problems.length === 0 ? { ok: true } : { ok: false, problems };
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Get assertion objects for a captured function.
 *
 * Returns null if:
 *   - The function has no embedded records (not captured yet).
 *   - Assertions are disabled (__assertionsEnabled is false).
 *
 * When enabled, returns { checkEntry, checkExit, checkBoth, recordCount }.
 *
 * API contract:
 *
 *   checkEntry(jsArgs, liveStateBefore):
 *     Find the matching captured record for the given (args, pre-call state).
 *     jsArgs: the arguments passed to the JS function (object or null).
 *     liveStateBefore: [{key, val}] — pre-call game state snapshot.
 *     Returns: the matched record (to pass to checkExit) or null (no match
 *     → no assertion fired, this invocation is not in the capture corpus).
 *     Does NOT throw.
 *
 *   checkExit(matchedRecord, jsResult, liveStateAfter):
 *     Assert that the JS result matches the captured record.
 *     matchedRecord: the record from checkEntry (null → no-op).
 *     jsResult: the value returned by the JS function.
 *     liveStateAfter: [{key, val}] — post-call game state dump.
 *     Throws an Error if result or state diverges from captured C ground truth.
 *
 *   checkBoth(jsArgs, liveStateBefore, jsResult, liveStateAfter):
 *     Convenience: checkEntry + checkExit in one call.
 *     Returns the matched record (or null if no match — no assertion fired).
 *     Throws on divergence.
 *
 *   recordCount: number of embedded records for this function.
 */
export function getAssertionsForFn(fnName) {
    if (!__assertionsEnabled) return null;
    const records = EMBEDDED_RECORDS[fnName];
    if (!records || records.length === 0) return null;

    return {
        checkEntry(jsArgs, liveStateBefore) {
            return findMatchingRecord(fnName, jsArgs, liveStateBefore);
        },

        checkExit(matchedRecord, jsResult, liveStateAfter) {
            if (matchedRecord === null || matchedRecord === undefined) return;
            const retCheck = checkReturnValue(jsResult, matchedRecord['return']);
            if (!retCheck.ok) {
                const reps = (matchedRecord.representatives || []).join(', ') || '(no reps)';
                throw new Error(
                    'assertion(' + fnName + '): ' + retCheck.message
                    + ' [record: ' + reps + ']'
                );
            }
            if (Array.isArray(matchedRecord.state_after_diff)
                && matchedRecord.state_after_diff.length > 0) {
                const sc = checkStateAfterDiff(
                    matchedRecord.state_after_diff,
                    matchedRecord.state_before,
                    liveStateAfter
                );
                if (!sc.ok) {
                    const reps = (matchedRecord.representatives || []).join(', ') || '(no reps)';
                    throw new Error(
                        'assertion(' + fnName + '): state_after_diff diverges from C ground truth'
                        + ' [record: ' + reps + ']\n'
                        + sc.problems.join('\n')
                    );
                }
            }
        },

        checkBoth(jsArgs, liveStateBefore, jsResult, liveStateAfter) {
            const matched = findMatchingRecord(fnName, jsArgs, liveStateBefore);
            if (matched === null) return null;
            const retCheck = checkReturnValue(jsResult, matched['return']);
            if (!retCheck.ok) {
                const reps = (matched.representatives || []).join(', ') || '(no reps)';
                throw new Error(
                    'assertion(' + fnName + '): ' + retCheck.message
                    + ' [record: ' + reps + ']'
                );
            }
            if (Array.isArray(matched.state_after_diff)
                && matched.state_after_diff.length > 0) {
                const sc = checkStateAfterDiff(
                    matched.state_after_diff,
                    matched.state_before,
                    liveStateAfter
                );
                if (!sc.ok) {
                    const reps = (matched.representatives || []).join(', ') || '(no reps)';
                    throw new Error(
                        'assertion(' + fnName + '): state_after_diff diverges from C ground truth'
                        + ' [record: ' + reps + ']\n'
                        + sc.problems.join('\n')
                    );
                }
            }
            return matched;
        },

        get recordCount() { return records.length; },
    };
}

/**
 * List all functions with embedded assertion records.
 * Returns [{ fnName, recordCount }]. Useful for test discovery.
 */
export function listCapturedFunctions() {
    return Object.entries(EMBEDDED_RECORDS).map(([fnName, recs]) => ({
        fnName,
        recordCount: recs.length,
    }));
}

/**
 * Return the embedded records for a function (for debugging / test tooling).
 * Returns [] if no records exist for that function.
 */
export function getEmbeddedRecords(fnName) {
    return EMBEDDED_RECORDS[fnName] || [];
}
